INSERT INTO schema_migrations(version,name,checksum)
SELECT '0025','0025_bcmd_unified_sources.sql','cebaccf842da6323cd01878a6969627aa317f68a19c307008b633286e74e96c8'
WHERE @napa_pre_ok AND @napa_post_ok AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE version='0025');
SELECT '0025' AS version,
 CASE WHEN @napa_pre_ok AND @napa_post_ok AND (SELECT COUNT(*) FROM schema_migrations WHERE version='0025' AND name='0025_bcmd_unified_sources.sql' AND checksum='cebaccf842da6323cd01878a6969627aa317f68a19c307008b633286e74e96c8')=1 THEN 'VERIFIED'
      WHEN @napa_target_ok AND @napa_locked=1 AND @napa_post_ok AND (SELECT COUNT(*) FROM schema_migrations WHERE version='0025' AND name='0025_bcmd_unified_sources.sql' AND checksum='cebaccf842da6323cd01878a6969627aa317f68a19c307008b633286e74e96c8')=1 THEN 'ALREADY_RECORDED'
      ELSE 'STOP' END AS step_status,
 @napa_target_ok AS target_ok,@napa_pre_ok AS preflight_ok,@napa_post_ok AS postflight_ok;
SELECT IF(@napa_locked=1,RELEASE_LOCK('tuloy_schema_migrate'),0) AS migration_lock_released;
